from __future__ import annotations
from array import array as _vsc_array
# Generated by Viscosity: bounds check matching list's IndexError.
def _vsc_ix(c, i):
    if -c.n <= i < c.n:
        return i
    raise IndexError('list index out of range')
# Generated by Viscosity: like iterating a list, re-checks the length each step.
def _vsc_iter(c):
    i = 0
    while i < c.n:
        yield i
        i += 1
# Generated by Viscosity: "vs" stored as a struct of arrays (fields x, y, w).
class _Vsc_vs:
    __slots__ = ('n', 'x', 'y', 'w')
    def __init__(self):
        self.n = 0
        self.x = _vsc_array('d')
        self.y = _vsc_array('d')
        self.w = _vsc_array('d')
    def append(self, v0, v1, v2):
        self.x.append(v0)
        self.y.append(v1)
        self.w.append(v2)
        self.n += 1
    def __len__(self):
        return self.n
    @classmethod
    def _of(cls, *v):
        c = cls()
        for i in range(0, len(v), 3):
            c.append(v[i + 0], v[i + 1], v[i + 2])
        return c

from dataclasses import dataclass
import math

@dataclass
class V:
    x: float
    y: float
    w: float = -1.5

# @viscosity soa
vs = _Vsc_vs()
# @viscosity aos
keep = []
others = []  # not annotated: CPython's default keeps objects

for i in range(200):
    vs.append(i * 1.0, math.sqrt(i), -1.5)
    keep.append(V(1.0, 2.0, w=3.0))
    others.append(V(0.5, 0.25))

def norm_vs():
    total = 0.0
    for v in _vsc_iter(vs):
        total += math.hypot(vs.x[v], vs.y[v]) * vs.w[v]
    return total

def norm_keep():
    total = 0.0
    for v in keep:
        total += v.x * v.w
    return total

print(round(norm_vs(), 6), round(norm_keep(), 6), len(others))
for k in range(len(vs)):
    if k % 3 == 0:
        vs.x[k] -= 1.0
    elif k % 3 == 1:
        vs.y[k] *= 2.0
    else:
        continue
print(vs.x[0], vs.y[1], vs.x[2], others[0].y)
